const parseHmsToSec = (str) => {
  if (!str || typeof str !== "string") return 0;
  const m = str.trim().match(/^(\d+):(\d{1,2}):(\d{1,2}(?:\.\d+)?)/);
  if (!m) return 0;
  return parseInt(m[1], 10) * 3600 + parseInt(m[2], 10) * 60 + parseFloat(m[3]);
};

const resolveProbeDuration = (p) => {
  if (!p) return null;
  let d = Number(p.format?.duration);
  if (d > 0 && Number.isFinite(d)) return d;
  const v = (p.streams || []).find(s => s.codec_type === "video" && !s.disposition?.attached_pic && !s.disposition?.timed_thumbnails);
  if (v) {
    const vd = Number(v.duration);
    if (vd > 0 && Number.isFinite(vd)) return vd;
    if (v.tags) {
      const k = Object.keys(v.tags).find(t => t.toUpperCase() === "DURATION" || t.toUpperCase().startsWith("DURATION-"));
      if (k) {
        const td = parseHmsToSec(v.tags[k]);
        if (td > 0) return td;
      }
    }
  }
  const a = (p.streams || []).find(s => s.codec_type === "audio");
  if (a) {
    const ad = Number(a.duration);
    if (ad > 0 && Number.isFinite(ad)) return ad;
    if (a.tags) {
      const k = Object.keys(a.tags).find(t => t.toUpperCase() === "DURATION" || t.toUpperCase().startsWith("DURATION-"));
      if (k) {
        const td = parseHmsToSec(a.tags[k]);
        if (td > 0) return td;
